reference_solution:
def combine(n, k):
    res, cur = [], []
    def bt(start):
        if len(cur) == k:
            res.append(cur[:])
            return
        for i in range(start, n + 1):
            cur.append(i)
            bt(i + 1)
            cur.pop()
    bt(1)
    return res

brute_force_solution:
import itertools
def combine(n, k):
    return [list(c) for c in itertools.combinations(range(1, n + 1), k)]

